// Routing da tag CRM → template_id, area jurídica, nome do serviço
// v8 (16 Mai 2026): TAG_TO_SERVICE alinhado com renames das tags 24 e 29
// (Empresa Alteracoes → Empresas - Alteracoes; Insolvencia → Empresas - Insolvencia).
// v7 (16 Mai 2026): tag 13 (ex-Diversos) renomeada para "Mentoria",
// agora aponta para TPL #165 (4 tarefas dedicadas).
// v6 (15 Mai 2026): Adicionado fallback para tags não-mapeadas →
// Serviço Jurídico Diverso (TPL #117). Workflow nunca falha por tag desconhecida.
// v5 (15 Mai 2026): Adicionada tag 31 (Serviço Jurídico Diverso).
// v4 (26 Abr 2026): TAG_TO_TEMPLATE actualizado — tags 20-29 agora
// apontam para templates bonitos (117, 122-131) em vez de feios.

const TAG_TO_TEMPLATE = {
  14: 97,   // Nacionalidade Portuguesa → TPL Nacionalidade
  15: 98,   // Visto Português → TPL Visto
  8:  99,   // Empresas → TPL Empresa
  12: 100,  // Consulta Técnica → TPL Consulta
  13: 165,  // Mentoria → TPL Mentoria Advogar em Portugal (16 Mai 2026)
  16: 113,  // Impostos — Saída Fiscal BR → TPL Saída Fiscal Brasil
  17: 114,  // Impostos — IFICI → TPL IFICI
  19: 116,  // Impostos — Consulta Fiscal IRS → TPL Consulta Fiscal IRS
  20: 122,  // Casamento → TPL Casamento
  21: 123,  // Homologação Divórcio → TPL Homologação Divórcio
  22: 124,  // Divórcio Extrajudicial → TPL Divórcio Extrajudicial
  23: 125,  // Análise de Contrato → TPL Análise de Contrato
  24: 126,  // Empresas - Alteracoes → TPL Empresas Alterações Societárias
  25: 127,  // Notificação Extrajudicial → TPL Notificação Extrajudicial
  26: 128,  // Renovação AR → TPL Renovação AR
  27: 129,  // Ação AIMA Agendamento → TPL Ação AIMA Agendamento
  28: 130,  // Ação AIMA Expulsão → TPL Ação AIMA Expulsão
  29: 131,  // Empresas - Insolvencia → TPL Insolvência
  31: 117,  // Serviço Jurídico Diverso → TPL Serviço Jurídico (15 Mai 2026)
};

const TAG_TO_AREA = {
  14: 'imigracao', 15: 'imigracao', 7: 'imigracao',
  8: 'empresas', 9: 'familia',
  11: 'imobiliario', 12: 'documentos',
  13: 'diversos',    // Mentoria (16 Mai 2026)
  16: 'impostos', 17: 'impostos', 19: 'impostos',
  20: 'familia',     // Casamento
  21: 'familia',     // Homologação Divórcio
  22: 'familia',     // Divórcio Extrajudicial
  23: 'diversos',    // Análise de Contrato
  24: 'empresas',    // Empresas - Alteracoes (16 Mai 2026)
  25: 'diversos',    // Notificação Extrajudicial
  26: 'imigracao',   // Renovação AR
  27: 'imigracao',   // Ação AIMA Agendamento
  28: 'imigracao',   // Ação AIMA Expulsão
  29: 'empresas',    // Empresas - Insolvencia (16 Mai 2026)
  31: 'diversos',    // Serviço Jurídico Diverso (15 Mai 2026)
};

const TAG_TO_SERVICE = {
  14: 'Nacionalidade Portuguesa', 15: 'Visto Português',
  7: 'Imigração (Geral)', 8: 'Abertura de Empresa',
  9: 'Família', 11: 'Imobiliário',
  12: 'Consulta Técnica',
  13: 'Mentoria — Advogar em Portugal',  // 16 Mai 2026
  16: 'Impostos — Saída Fiscal BR',
  17: 'Impostos — IFICI',
  19: 'Impostos — Consulta Fiscal IRS',
  20: 'Casamento em Portugal',
  21: 'Homologacao de Divorcio',
  22: 'Divorcio Extrajudicial',
  23: 'Analise de Contrato',
  24: 'Empresas - Alteracoes',           // 16 Mai 2026 (era 'Empresa - Alteracoes Societarias')
  25: 'Notificacao Extrajudicial',
  26: 'Renovacao de AR',
  27: 'Acao AIMA - Agendamento',
  28: 'Acao AIMA - Expulsao',
  29: 'Empresas - Insolvencia',          // 16 Mai 2026 (era 'Insolvencia')
  31: 'Serviço Jurídico Diverso',        // 15 Mai 2026
};

const body = $input.first().json.body || $input.first().json;
const tagIds = body.tag_ids || [];

let templateId = null;
let lawArea = 'diversos';
let serviceType = '';

for (const tagId of tagIds) {
  if (TAG_TO_TEMPLATE[tagId]) templateId = TAG_TO_TEMPLATE[tagId];
  if (TAG_TO_AREA[tagId]) lawArea = TAG_TO_AREA[tagId];
  if (TAG_TO_SERVICE[tagId]) serviceType = TAG_TO_SERVICE[tagId];
}

// FALLBACK (v6 — 15 Mai 2026):
// Se nenhuma tag mapeada matched (tag nova/desconhecida, ou lead sem tag),
// usa Serviço Jurídico Diverso (TPL #117). Carolina pode criar tags livres
// no CRM sem quebrar o automatismo. Workflow nunca falha por tag desconhecida.
if (!templateId) {
  templateId = 117;
  lawArea = 'diversos';
  serviceType = serviceType || 'Serviço Jurídico Diverso';
}

// Limpar prefixos/sufixos ruidosos do nome do lead
let cleanName = (body.name || 'Sem nome')
  .replace(/^\[Lead\]\s*/i, '')
  .replace(/\s*-\s*Fale Conosco CF$/i, '')
  .replace(/\s*-\s*Reunião Mentoria Advogar em Portugal$/i, '')
  .replace(/\s*-\s*Lead Manual$/i, '')
  .replace(/^Consulta Calendly\s*[—–-]\s*/i, '')
  .replace(/^Fale Conosco CF\s*-\s*/i, '')
  .trim();

const contactName = body.contact_name || cleanName.split(' — ')[0];
const email = body.email_from || '';
const phone = body.phone || '';

return [{
  json: {
    lead_name: cleanName,
    contact_name: contactName,
    email: email,
    phone: phone,
    expected_revenue: body.expected_revenue || 0,
    tag_ids: tagIds,
    template_id: templateId,
    law_area: lawArea,
    service_type: serviceType,
  }
}];

// Buscar partner existente (por email OU telefone 9 dígitos); criar se não achar.
// Resolve o caso "cliente volta após X anos" — reusa partner em vez de criar duplicado.
const data = $input.first().json;
const email = data.email;
const name = data.contact_name;
const phone = data.phone;

async function rpc(model, method, args, kwargs) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://odoo.telejud.com/jsonrpc',
    headers: { 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: ['odoo18', 2, '0fd980f86424e522826d5a2da33e63a5d8a095c1', model, method, args, kwargs || {}],
      }
    }
  });
  if (r.error) {
    throw new Error('Odoo error: ' + JSON.stringify(r.error));
  }
  return r.result;
}
const rpcBound = rpc.bind(this);

let partnerId = null;
let matchedBy = null;

// 1) Busca por email exacto
if (email) {
  const found = await rpcBound('res.partner', 'search', [[['email', '=', email]]], { limit: 1 });
  if (found && found.length > 0) {
    partnerId = found[0];
    matchedBy = 'email';
  }
}

// 2) Fallback: busca por telefone (últimos 9 dígitos) em phone OR mobile
if (!partnerId && phone) {
  const last9 = String(phone).replace(/\D/g, '').slice(-9);
  if (last9.length === 9) {
    const found = await rpcBound('res.partner', 'search',
      [['|', ['phone', 'ilike', last9], ['mobile', 'ilike', last9]]],
      { limit: 1 });
    if (found && found.length > 0) {
      partnerId = found[0];
      matchedBy = 'phone';
    }
  }
}

// 3) Criar se não achar
if (!partnerId) {
  partnerId = await rpcBound('res.partner', 'create',
    [{ name: name, email: email || false, phone: phone || false, is_company: false }], {});
  matchedBy = 'created';
}

return [{
  json: {
    ...data,
    partner_id: partnerId,
    partner_matched_by: matchedBy,
  }
}];

// Mapeia tag CRM → product.product.id para usar na linha da Sale Order.
// Tags específicas têm prioridade sobre genéricas (fallback dentro de categoria).
// v7 (16 Mai 2026): tag 13 (ex-Diversos) renomeada para "Mentoria" e mapeada
// para produto #45 (TPL #165 com 4 tarefas dedicadas).
const TAG_TO_PRODUCT = {
  14: 14,  // Nacionalidade Portuguesa
  15: 15,  // Visto Português
  8:  16,  // Empresas → Abertura Empresa Unipessoal
  13: 45,  // Mentoria → Mentoria — Advogar em Portugal (produto #45, TPL #165) — 16 Mai 2026
  7:  17,  // Imigração genérica → Serviço Jurídico
  12: 12,  // Documentos → Consulta Técnica
  16: 21,  // Impostos — Saída Fiscal BR
  17: 22,  // Impostos — IFICI
  19: 24,  // Impostos — Consulta Fiscal IRS PT → produto #24 (TPL #116) — FIX 15 Mai 2026
  20: 25,  // Casamento em Portugal
  21: 26,  // Homologação Divórcio
  22: 27,  // Divórcio Extrajudicial
  23: 28,  // Análise de Contrato
  24: 29,  // Empresa Alterações Societárias
  25: 30,  // Notificação Extrajudicial
  26: 31,  // Renovação AR
  27: 32,  // Ação AIMA Agendamento
  28: 33,  // Ação AIMA Expulsão
  29: 34,  // Insolvência
  31: 17,  // Serviço Jurídico Diverso → Serviço Jurídico (produto #17, TPL #117)
};

// Tags genéricas — usar como fallback dentro de uma categoria,
// só se nenhuma específica matched.
// Nota: tag 13 (Mentoria) NÃO está aqui — é específica para mentoria.
const GENERIC_TAGS = new Set([7, 31]);

const FALLBACK_PRODUCT_ID = 17;

const results = [];
for (const item of $input.all()) {
  const data = item.json;
  const tagIds = Array.isArray(data.tag_ids) ? data.tag_ids : [];
  let productId = null;
  let matchedTag = null;

  // Passagem 1: tags específicas
  for (const tid of tagIds) {
    if (TAG_TO_PRODUCT[tid] && !GENERIC_TAGS.has(tid)) {
      productId = TAG_TO_PRODUCT[tid];
      matchedTag = tid;
      break;
    }
  }

  // Passagem 2: tags genéricas (Imigração geral, Serviço Jurídico Diverso)
  if (!productId) {
    for (const tid of tagIds) {
      if (TAG_TO_PRODUCT[tid]) {
        productId = TAG_TO_PRODUCT[tid];
        matchedTag = tid;
        break;
      }
    }
  }

  // Fallback final (lead sem tag ou tag desconhecida) — usar com log
  const usedFallback = (productId === null);
  if (usedFallback) {
    productId = FALLBACK_PRODUCT_ID;
    console.warn(
      `[FALLBACK] Lead ${data.id || '?'} '${data.name || '?'}' sem tag mapeada. ` +
      `tag_ids recebidos: ${JSON.stringify(tagIds)}. ` +
      `Carolina deve aplicar tag específica e re-processar.`
    );
  }

  results.push({
    json: {
      ...data,
      product_id: productId,
      matched_tag_id: matchedTag,
      used_fallback: usedFallback,
    }
  });
}
return results;

// Cria Sale Order em rascunho, sem linhas. Linhas adicionadas no próximo node.
// Com protecção anti-duplicado: aborta se já existe SO draft para este lead.
const data = $input.first().json;
// lead_id vem directamente do webhook inicial
const leadId = $('Webhook Lead Won').first().json.body.id;
async function rpc(model, method, args, kwargs) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://odoo.telejud.com/jsonrpc',
    headers: { 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: ['odoo18', 2, '0fd980f86424e522826d5a2da33e63a5d8a095c1', model, method, args, kwargs || {}],
      }
    }
  });
  if (r.error) {
    throw new Error('Odoo error (sale.order create): ' + JSON.stringify(r.error));
  }
  return r.result;
}
const rpcBound = rpc.bind(this);
if (!data.partner_id) {
  throw new Error('partner_id é obrigatório para criar SO');
}
if (!leadId) {
  throw new Error('lead_id ausente — não conseguiu ler do Webhook Lead Won');
}
// PROTECÇÃO ANTI-DUPLICADO: aborta se já existe SO draft para este lead.
const existingSOs = await rpcBound('sale.order', 'search', [[
  ['opportunity_id', '=', leadId],
  ['state', '=', 'draft']
]], {});
if (existingSOs.length > 0) {
  throw new Error(`Duplicate skip — SO #${existingSOs[0]} (draft) já existe para lead ${leadId}`);
}
// Cria SO
const soId = await rpcBound('sale.order', 'create', [{
  partner_id: data.partner_id,
  opportunity_id: leadId,
  origin: 'Lead CRM — ' + (data.service_type || 'Serviço'),
  note: 'Criado automaticamente via n8n a partir de lead ganho.\n' +
        'Lead ID: ' + leadId + '\n' +
        'Tag matched: ' + (data.matched_tag_id !== null ? data.matched_tag_id : 'fallback') + '\n' +
        'Service: ' + (data.service_type || '—') + '\n' +
        'Partner matched by: ' + (data.partner_matched_by || '—'),
}], {});
return [{
  json: {
    ...data,
    sale_order_id: soId,
    lead_id: leadId,
  }
}];

// Adiciona 1 linha à SO com o produto mapeado.
// Lógica de preço (v2 — 16 Mai 2026):
//   1. Se lead tem expected_revenue > 0 (Carolina definiu na Proposta Enviada) → usa esse valor
//   2. Senão → puxa do product.lst_price (catálogo)
//   3. Se ambos = 0 → SO sai com €0, Carolina edita manualmente
// SO fica em estado 'draft' (rascunho). Carolina confirma manualmente depois no Odoo.

const data = $input.first().json;

async function rpc(model, method, args, kwargs) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://odoo.telejud.com/jsonrpc',
    headers: { 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: ['odoo18', 2, '0fd980f86424e522826d5a2da33e63a5d8a095c1', model, method, args, kwargs || {}],
      }
    }
  });
  if (r.error) {
    throw new Error('Odoo error (sale.order.line create): ' + JSON.stringify(r.error));
  }
  return r.result;
}
const rpcBound = rpc.bind(this);

if (!data.sale_order_id) {
  throw new Error('sale_order_id ausente — node anterior falhou');
}
if (!data.product_id) {
  throw new Error('product_id ausente — mapear tag/produto falhou');
}

// Decidir preço da linha
const expectedRevenue = parseFloat(data.expected_revenue) || 0;
let priceSource = '';
let lineValues = {
  order_id: data.sale_order_id,
  product_id: data.product_id,
  product_uom_qty: 1,
};

if (expectedRevenue > 0) {
  // Carolina definiu valor no lead (ex: proposta enviada) → vence o catálogo
  lineValues.price_unit = expectedRevenue;
  priceSource = 'lead.expected_revenue';
} else {
  // Sem valor no lead → Odoo puxa list_price do produto via onchange (default behaviour)
  priceSource = 'product.list_price (default)';
}

const lineId = await rpcBound('sale.order.line', 'create', [lineValues], {});

return [{
  json: {
    ...data,
    sale_order_line_id: lineId,
    price_source: priceSource,
    price_applied: expectedRevenue > 0 ? expectedRevenue : null,
  }
}];

const data = $input.first().json;

return [{
  json: {
    status: 'ok',
    message: 'Projecto criado automaticamente a partir do lead ganho.',
    lead_name: data.lead_name,
    lead_id: data.lead_id,
    contact_name: data.contact_name,
    partner_id: data.partner_id,
    sale_order_id: data.sale_order_id,
    project_id: data.project_id,
    project_name: data.project_name,
    service_type: data.service_type,
    matched_tag_id: data.matched_tag_id,
    used_fallback: data.used_fallback,
    so_url: 'https://odoo.telejud.com/odoo/sales/' + data.sale_order_id,
    project_url: 'https://odoo.telejud.com/odoo/project/' + data.project_id,
  }
}];

// Cria project.project COPIANDO do template mapeado pela tag.
// NÃO usa sale_line_id — evita auto-confirm da SO via _ensure_sale_order_linked.
// Template.copy() traz as tasks automaticamente.
// FASE 5: após copy, recalcula date_deadline das tasks aplicando offset de dias
// entre BASE_DATE (2026-04-24, data de criação dos templates) e hoje.
// FIX BUG: valor_honorarios usa amount_untaxed da SO (verdade contabilística)
// em vez de expected_revenue do lead (placeholder do Make).
const data = $input.first().json;
async function rpc(model, method, args, kwargs) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://odoo.telejud.com/jsonrpc',
    headers: { 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: ['odoo18', 2, '0fd980f86424e522826d5a2da33e63a5d8a095c1', model, method, args, kwargs || {}],
      }
    }
  });
  if (r.error) {
    throw new Error('Odoo error (project.project copy): ' + JSON.stringify(r.error));
  }
  return r.result;
}
const rpcBound = rpc.bind(this);
if (!data.template_id) {
  throw new Error('template_id ausente — tag do lead sem mapping de template. Adicionar tag antes de arrastar para Cliente Novo.');
}
if (!data.partner_id) {
  throw new Error('partner_id ausente');
}

// Helper: normalizar valor que pode vir como [id, name] de read() many2one
function normalize(v) {
  if (Array.isArray(v)) return v[0] || false;
  return v || false;
}

// Ler campos lead_* do lead original (expected_revenue NÃO é mais usado para honorários)
const leadData = await rpcBound('crm.lead', 'read',
  [[data.lead_id], ['lead_whatsapp', 'lead_calendly_link', 'lead_meet_link',
                     'lead_data_triagem', 'lead_airtable_id', 'lead_respostas']], {});
const lead = leadData[0] || {};

// FIX: defesa em profundidade contra arrays vindos do read()
lead.lead_whatsapp = normalize(lead.lead_whatsapp);
lead.lead_calendly_link = normalize(lead.lead_calendly_link);
lead.lead_meet_link = normalize(lead.lead_meet_link);
lead.lead_data_triagem = normalize(lead.lead_data_triagem);
lead.lead_airtable_id = normalize(lead.lead_airtable_id);
lead.lead_respostas = normalize(lead.lead_respostas);

// FIX BUG: ler amount_untaxed da SO (verdade contabilística — sem IVA)
// Se SO não existir ou amount=0, fallback para 0.0
let valorHonorarios = 0.0;
if (data.sale_order_id) {
  const soData = await rpcBound('sale.order', 'read',
    [[data.sale_order_id], ['amount_untaxed']], {});
  if (soData && soData[0]) {
    valorHonorarios = soData[0].amount_untaxed || 0.0;
  }
}

// Nome do projecto: "Nome Cliente — Tipo Serviço"
const projectName = `${data.contact_name} — ${data.service_type || 'Serviço'}`;
// project.project.copy(template_id, defaults)
// Odoo duplica template com todas as tasks + aplica os overrides dos defaults
const projectIdRaw = await rpcBound('project.project', 'copy', [data.template_id, {
  name: projectName,
  partner_id: data.partner_id,
  user_id: 6,  // Carolina Felix
  active: true,
  // Campos law_firm_core
  lead_whatsapp: lead.lead_whatsapp,
  lead_calendly_link: lead.lead_calendly_link,
  lead_meet_link: lead.lead_meet_link,
  lead_data_triagem: lead.lead_data_triagem,
  lead_airtable_id: lead.lead_airtable_id,
  lead_respostas: lead.lead_respostas,
  area_direito: data.law_area || 'diversos',
  tipo_servico: data.service_type || '',
  valor_honorarios: valorHonorarios,
}], {});

// FIX: projectId pode vir como int OU array — normalizar para int
const projectId = Array.isArray(projectIdRaw) ? projectIdRaw[0] : projectIdRaw;

// ======================================================================
// PARTE B.1 (18 Mai 2026) — Mapear tags do CRM para tags do projecto
// ======================================================================
// Le lead.tag_ids (crm.tag), procura/cria equivalente em project.tags por nome,
// depois adiciona ao project.project recem-criado.
// addon law_firm_core ja sincroniza crm.tag <-> project.tags via override,
// portanto na pratica o search vai sempre encontrar; lazy-create eh fallback de seguranca.

const leadTagsData = await rpcBound('crm.lead', 'read',
  [[data.lead_id], ['tag_ids']], {});
