      // Lazy-create (defesa em profundidade — addon sync deveria ja ter criado)
      ptagId = await rpcBound('project.tags', 'create', [{ name: ct.name }], {});
    }
    projectTagIds.push(ptagId);
  }

  // Adicionar ao projecto (formato many2many: [(4, id)])
  if (projectTagIds.length > 0) {
    await rpcBound('project.project', 'write',
      [[projectId], { tag_ids: projectTagIds.map(id => [4, id]) }], {});
  }
}
