// FASE 5 — Recalcular date_deadline das tasks com offset relativo a hoje
// ======================================================================
// BASE_DATE = 2026-04-24 (data em que os templates foram criados).
// Calcular delta entre hoje e BASE_DATE em dias inteiros e aplicar a cada task.
// Tasks sem date_deadline continuam sem deadline.
const BASE_DATE_MS = Date.UTC(2026, 3, 24); // mês é 0-indexed: 3 = Abril
const today = new Date();
const todayMs = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
const deltaDays = Math.round((todayMs - BASE_DATE_MS) / (24 * 60 * 60 * 1000));

let ta***REDACTED*** = 0;
if (deltaDays !== 0) {
  // Ler tasks do projecto novo com date_deadline preenchido
  const tasks = await rpcBound('project.task', 'search_read',
    [[['project_id', '=', projectId], ['date_deadline', '!=', false]],
     ['id', 'date_deadline']], {});

  for (const task of tasks) {
    // date_deadline vem como 'YYYY-MM-DD HH:MM:SS' ou 'YYYY-MM-DD'
    const dateStr = task.date_deadline.split(' ')[0]; // só YYYY-MM-DD
    const [yr, mo, da] = dateStr.split('-').map(Number);
    const origMs = Date.UTC(yr, mo - 1, da);
    const newMs = origMs + deltaDays * 24 * 60 * 60 * 1000;
    const nd = new Date(newMs);
    const newDate = `${nd.getUTCFullYear()}-${String(nd.getUTCMonth() + 1).padStart(2, '0')}-${String(nd.getUTCDate()).padStart(2, '0')}`;
    await rpcBound('project.task', 'write',
      [[task.id], { date_deadline: newDate }], {});
    ta***REDACTED***++;
  }
}

